// スケルトン限定（Step 9）: 写真の添付を実装するまで、架空の 1x1 JPEG を「添付済みの写真」として使う。
// BR1.1（写真必須）の一時的な例外はこのファイルと app/new.tsx の呼び出しだけに閉じ込め、Step 10 で削除する。
import { File, Paths } from 'expo-file-system';

const TINY_JPEG_BASE64 =
  '';

/** 端末のキャッシュ領域に架空の写真を用意し、その参照を返す */
export function ensureSkeletonPlaceholderPhoto(): string {
  const file = new File(Paths.cache, 'skeleton-placeholder.jpg');
  if (!file.exists) {
    file.write(TINY_JPEG_BASE64, { encoding: 'base64' });
  }
  return file.uri;
}
